// Models for Family Invitations sent to adult members.

class FamilyInvitationSummary {
  const FamilyInvitationSummary({
    required this.id,
    this.emailMasked,
    this.relationshipType,
    required this.status,
    this.expiresAt,
  });

  factory FamilyInvitationSummary.fromJson(Map<String, dynamic> json) =>
      FamilyInvitationSummary(
        id: json['id'] as String,
        emailMasked: json['emailMasked'] as String?,
        relationshipType: json['relationshipType'] as String?,
        status: json['status'] as String? ?? 'Pending',
        expiresAt: DateTime.tryParse(json['expiresAt'] as String? ?? '')?.toLocal(),
      );

  final String id;
  final String? emailMasked;
  final String? relationshipType;
  final String status;
  final DateTime? expiresAt;
}

class FamilyInvitationIssued {
  const FamilyInvitationIssued({
    required this.id,
    required this.token,
    this.expiresAt,
  });

  factory FamilyInvitationIssued.fromJson(Map<String, dynamic> json) =>
      FamilyInvitationIssued(
        id: json['id'] as String,
        token: json['token'] as String,
        expiresAt: DateTime.tryParse(json['expiresAt'] as String? ?? '')?.toLocal(),
      );

  final String id;
  final String token;
  final DateTime? expiresAt;
}
